CREATE OR REPLACE FUNCTION public.consume_post_slot(_user uuid,_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; INSERT INTO public.monthly_post_usage(post_id,user_id) VALUES(_id,_user) ON CONFLICT DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.guard_show_contact() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT NEW.show_contact THEN NEW.contact_phone:=NULL; NEW.public_photo:=''; NEW.public_brand:=''; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF p.module='vehicle' AND NOT (public.has_paid_bell(auth.uid()) OR public.has_role(auth.uid(),'admin') OR p.user_id=auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN jsonb_build_object('description',p.description,'goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date,'vehicle_name',CASE WHEN p.module='vehicle' THEN p.vehicle_name ELSE NULL END,'vehicle_number',CASE WHEN p.module='vehicle' THEN p.vehicle_number ELSE NULL END,'driver_name',CASE WHEN p.module='vehicle' AND p.show_contact THEN p.driver_name ELSE NULL END,'contact_phone',CASE WHEN p.show_contact THEN p.contact_phone ELSE NULL END,'public_brand',CASE WHEN p.show_contact THEN p.public_brand ELSE '' END,'public_photo',CASE WHEN p.show_contact AND p.public_photo ~ '^https://' THEN p.public_photo ELSE '' END); END $$;
REVOKE ALL ON FUNCTION public.get_post_details(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_post_details(uuid) TO anon,authenticated,service_role;